package org.strongswan.android.rookstride;
import org.junit.Test;
import static org.junit.Assert.*;
public class AppNavigationTest {
 @Test public void clickingAnAncestorCollapsesDeeperHistory(){AppNavigation n=new AppNavigation();n.go("Add");n.go("Protocols");n.go("VPN");n.go("People");n.ancestor("Protocols");assertEquals("Protocols",n.current());assertTrue(n.back());assertEquals("Add",n.current());n.ancestor("Protocols");assertEquals("Protocols",n.current());n.ancestor("Protocols");assertTrue(n.back());assertEquals("Home",n.current());}
 @Test public void addFlowAndSecondaryTabsKeepThePreviousStep(){AppNavigation n=new AppNavigation();n.go("Add");n.go("Setup");n.go("Protocols");assertTrue(n.back());assertEquals("Setup",n.current());n.back();assertEquals("Add",n.current());n.back();assertEquals("Home",n.current());n.go("VPN");n.go("Settings");n.main("Stories");n.main("AppSettings");n.back();assertEquals("Stories",n.current());n.back();assertEquals("Settings",n.current());n.main("Home");assertEquals("Home",n.current());assertFalse(n.back());}
 @Test public void setupAndServerControlsAreNestedAndBackRestoresThePreviousScreen(){AppNavigation n=new AppNavigation();assertEquals("Home",n.current());n.go("Setup");n.go("Protocols");assertTrue(n.back());assertEquals("Setup",n.current());n.go("VPN");n.go("People");assertTrue(n.back());assertEquals("VPN",n.current());}
 @Test public void recreatingDoesNotChangeTheSelectedFlow(){AppNavigation n=new AppNavigation();n.go("Setup");n.go("Protocols");AppNavigation restored=new AppNavigation();restored.restore(n.saved());assertEquals("Protocols",restored.current());restored.back();assertEquals("Setup",restored.current());restored.back();assertEquals("Home",restored.current());assertFalse(restored.back());}
 @Test public void mainDestinationsCannotExposeServerControls(){AppNavigation n=new AppNavigation();n.go("VPN");n.go("Settings");n.root("Stories");n.back();assertEquals("Home",n.current());assertFalse(n.back());try{n.root("People");fail();}catch(IllegalArgumentException expected){}}
 @Test public void protocolsDistinguishTheInstallerFromThePhoneEngine(){assertTrue(SingleProtocols.IKEV2.embedded());for(SingleProtocols p:new SingleProtocols[]{SingleProtocols.AWG,SingleProtocols.XRAY,SingleProtocols.OPENVPN}){assertTrue(p.embedded());assertFalse(p.packageName.isEmpty());assertTrue(p.port>0);}InstallationProgress progress=new InstallationProgress("protocol","test-id",1);assertEquals(7,progress.steps().length);assertTrue(progress.estimate().contains("min"));}
 @Test public void appAndServerSettingsHaveSeparateRestorableDestinations(){AppNavigation n=new AppNavigation();n.go("Protocols");n.go("ServerSettings");n.go("AppSettings");AppNavigation copy=new AppNavigation();copy.restore(n.saved());assertEquals("AppSettings",copy.current());copy.back();assertEquals("ServerSettings",copy.current());copy.back();assertEquals("Protocols",copy.current());assertTrue(AppNavigation.serverOnly("ServerSettings"));assertFalse(AppNavigation.serverOnly("AppSettings"));}
 @Test public void mainTabsKeepTheirIdentityWhileOpeningHelpAndReturning(){AppNavigation n=new AppNavigation();n.main("Routing");assertEquals("Routing",n.mainDestination());n.main("Routing");n.main("Stories");n.main("AppSettings");n.go("Guide");assertEquals("AppSettings",n.mainDestination());AppNavigation restored=new AppNavigation();restored.restore(n.saved());assertEquals("AppSettings",restored.mainDestination());restored.back();assertEquals("AppSettings",restored.current());restored.back();assertEquals("Stories",restored.current());restored.back();assertEquals("Routing",restored.current());restored.main("Home");assertFalse(restored.back());}
 @Test public void pairedPhysicalServerHasARestorableScopedDestination(){AppNavigation n=new AppNavigation();n.go("PairServer");n.go("Settings");AppNavigation copy=new AppNavigation();copy.restore(n.saved());assertTrue(copy.back());assertEquals("PairServer",copy.current());assertTrue(AppNavigation.serverOnly(copy.current()));assertTrue(copy.back());assertEquals("Home",copy.current());}
 @Test public void serversAreAnIndependentPrimaryDestinationWithRestorableMaintenance(){AppNavigation n=new AppNavigation();n.main("Servers");n.go("Protocols");n.go("ServerSettings");assertEquals("Servers",n.mainDestination());AppNavigation copy=new AppNavigation();copy.restore(n.saved());assertEquals("Servers",copy.mainDestination());copy.ancestor("Servers");assertEquals("Servers",copy.current());assertTrue(copy.back());assertEquals("Home",copy.current());}
 @Test public void repeatedServersSelectionDoesNotGrowHistory(){AppNavigation n=new AppNavigation();n.main("Servers");int size=n.saved().size();for(int i=0;i<5;i++)n.main("Servers");assertEquals(size,n.saved().size());n.main("Home");assertFalse(n.back());}
}
